import re

# Test more complex scenarios
patterns = {
    "default": r"a (.+?) c",
    "left_any": r"a ([^ ]+).*? c",
}

texts = [
    "a b c",           # no extra spaces
    "a   b   c",       # multiple spaces
    "text a hello world c more text",  # embedded in larger text
]

for name, pattern in patterns.items():
    print(f"{name}: {pattern!r}")
    for text in texts:
        m = re.search(pattern, text)
        if m:
            print(f"  search({text!r}) -> group(1)={m.group(1)!r}")
        else:
            print(f"  search({text!r}) -> NO MATCH")
    print()
EOF
